mapper.select:
select r.*, p.policy_name, p.compare_mode from data_reconcile_run_t r join data_reconcile_policy_t p on p.tid = r.policy_id and p.tenant_id = r.tenant_id where r.tenant_id = #{tenantId}
and r.status = #{status}
and p.policy_name like concat(concat('%', #{keyword}), '%')
order by r.created_time desc

select tid, business_key, diff_type, field_name,
       source_value_masked, target_value_masked,
       source_row_hash, target_row_hash,
       resolve_status, created_time
  from data_reconcile_diff_t
 where tenant_id = #{tenantId}
   and run_id = #{runId}

    and diff_type = #{diffType}

 order by created_time, tid

select diff_type, count(1) count
  from data_reconcile_diff_t
 where tenant_id = #{tenantId}
   and run_id = #{runId}
 group by diff_type

select *
  from data_access_agg_task_t
 where tenant_id = #{tenantId}
   and tid = #{taskId}
   and is_del = 0

mapper.update:
update data_reconcile_field_rule_t
   set is_del = 1,
       updated_by = #{operator},
       updated_time = #{updatedTime}
 where tenant_id = #{tenantId}
   and policy_id = #{policyId}
   and is_del = 0

mapper.select:
select source_field, target_field, source_data_type, target_data_type, sort_no
  from data_access_field_mapping
 where tenant_id = #{tenantId}
   and task_id = #{taskId}
   and is_del = 0
 order by sort_no, created_time

mapper.update:
update data_reconcile_policy_t
   set precheck_status = #{status},
       precheck_message = #{message},
       precheck_detail = #{detail},
       prechecked_at = #{now},
       updated_time = #{now}
 where tenant_id = #{tenantId}
   and tid = #{policyId}
   and is_del = 0

mapper.select:
select precheck_status
  from data_reconcile_policy_t
 where tenant_id = #{tenantId}
   and tid = #{policyId}
   and is_del = 0

mapper.update:
update data_reconcile_policy_t
   set status = #{status},
       next_run_at = case
           when #{enabled} = 1 and trigger_mode = 'CRON' then #{now}
           else next_run_at
       end,
       updated_time = #{now}
 where tenant_id = #{tenantId}
   and tid = #{policyId}
   and is_del = 0

mapper.select:
select upper_watermark
  from (
        select upper_watermark,
               row_number() over (
                   order by finished_at desc, created_time desc
               ) row_no
          from data_reconcile_run_t
         where tenant_id = #{tenantId}
           and policy_id = #{policyId}
           and status in ('CONSISTENT', 'INCONSISTENT')
           and upper_watermark is not null
  ) ranked
 where row_no = 1

mapper.insert:
insert into data_reconcile_run_t(
    tid, tenant_id, policy_id, policy_version, policy_snapshot,
    access_run_id, trigger_type, lower_watermark, upper_watermark,
    dedupe_key, status, created_by, created_time, updated_time
) values (
    #{tid}, #{tenantId}, #{policyId}, #{policyVersion}, #{policySnapshot},
    #{accessRunId}, #{triggerType}, #{lowerWatermark}, #{upperWatermark},
    #{dedupeKey}, 'PENDING', #{operator}, #{now}, #{now}
)

mapper.select:
select tid
  from data_reconcile_run_t
 where tenant_id = #{tenantId}
   and dedupe_key = #{dedupeKey}

mapper.update:
update data_reconcile_policy_t
   set last_run_at = #{updatedTime},
       updated_time = #{updatedTime}
 where tenant_id = #{tenantId}
   and tid = #{policyId}

update data_reconcile_run_t
   set cancel_requested = 1,
       updated_time = #{updatedTime}
 where tenant_id = #{tenantId}
   and tid = #{runId}
   and status in ('PENDING', 'INITIALIZING', 'RUNNING')

update data_reconcile_policy_t
   set next_run_at = #{nextRunAt}
 where tenant_id = #{tenantId}
   and tid = #{policyId}

mapper.select:
select *
  from data_reconcile_field_rule_t
 where tenant_id = #{tenantId}
   and policy_id = #{policyId}
   and is_del = 0
 order by sort_no, created_time

select count(1)
  from data_reconcile_policy_t
 where tenant_id = #{tenantId}
   and is_del = 0

    and status = #{status}

select status, count(1) count
  from data_reconcile_run_t
 where tenant_id = #{tenantId}
   and created_time >= #{createdSince}
 group by status
